;; curriculum: Multivariable (undergrad) — level curves; prerequisites: sine, mountain
;; math target: slicing z = f(x,y) at fixed heights gives contour lines; tight contours mean a steep climb.

app riya-level-contour "1.1.0"
"riya level 23 · Contour Ridge — the skyline is the slice of the hill z = f(x, y) at y = 0. Dashed contour levels z = 2, 4, 6 sit behind it; hop between terraces, then feel the right half tighten as the gradient steepens. Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup, rendered through math-canvas so the axes and the world's own function stay visible. Rebound into the riya-game-platformer organism."

;; @exposure internal

orbital RiyaContourOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaContourBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaContourPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaContourFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  type RiyaContourFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaContourPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaContourCurveSample = {
    x : number!
    y : number!
  }
  type RiyaContourCurve = {
    label : string
    color : string
    samples : [RiyaContourCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaContourGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaContourHop = {
    from : number!
    to : number!
    color : string
    label : string
  }

  entity RiyaContourState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaContourBody = { x: -9, y: 3.4, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaContourPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaContourFx] = []
    celebrated : boolean = false
    zoneId : string = "contour"
    platforms : [RiyaContourPlatform] = []
    curves : [RiyaContourCurve] = []
    guides : [RiyaContourGuide] = []
    hops : [RiyaContourHop] = []
  }
  entity ContourTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }


  trait ContourBody = Body.traits.PlatformerBody -> RiyaContourState {
    events {
      STEER: CONTOUR_STEER
      JUMP: CONTOUR_LEAP
      PLACE: CONTOUR_PLACE
      RESTART: CONTOUR_RESTART
      SET_PLATFORMS: CONTOUR_SET_PLATFORMS
      SET_SKATE_CURVE: CONTOUR_SET_SKATE_CURVE
      BODY_JUMPED: CONTOUR_JUMPED
      BODY_LANDED: CONTOUR_LANDED
      BODY_HAZARD: CONTOUR_HAZARD
      BODY_GOAL: CONTOUR_GOAL
      BODY_FELL: CONTOUR_FELL
      BODY_SKATE_START: CONTOUR_SKATE_ON
      BODY_SKATE_END: CONTOUR_SKATE_OFF
    }
    config {
      running: true
      spawn: { x: -9, y: 3.4, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: false
      skateSnap: 0.9
    }
  }

  trait ContourGate = Gate.traits.ObjectiveFlow -> RiyaContourState {
    events {
      PROGRESS: CONTOUR_PROGRESS
      GAME_END: CONTOUR_GAME_END
      RESTART: CONTOUR_RESTART
    }
    config { running: true }
  }

  trait ContourFx = Particles.traits.FxParticles -> RiyaContourState {
    events {
      BURST: CONTOUR_BURST
    }
    config { running: true }
  }

  trait ContourPickup = Pickup.traits.Pickup -> RiyaContourState {
    events {
      PICKED: CONTOUR_PICKED
      COLLECT: CONTOUR_COLLECT
      PICKUP_SET_COMPLETED: CONTOUR_PICKUP_SET_COMPLETED
      SET_FEATURES: CONTOUR_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait ContourLevelData -> @rebindable RiyaContourState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "contour"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn s @s))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          hops: (array/map @config.hops (fn h @h))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaContourPlatform]!
        stars : [RiyaContourPickup]!
        skateCurve : [RiyaContourCurveSample]
        curveOverlay : [RiyaContourCurve]
        guides : [RiyaContourGuide]
        hops : [RiyaContourHop]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Contours"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "z = 7 − x²/16"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "a contour map is the ridge seen from above; tighter contours mean a steeper climb"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 1.24
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge (top of tile b0: −2 + 3.24); the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = -1
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge (top of tile b11: −2 + 1); the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaContourPlatform] = [
        { id: "b0", x: -9.6, y: -2, width: 1.6, height: 3.24, type: "ground" }
        { id: "b1", x: -8, y: -2, width: 1.6, height: 5, type: "ground" }
        { id: "b2", x: -6.4, y: -2, width: 1.6, height: 6.44, type: "ground" }
        { id: "b3", x: -4.8, y: -2, width: 1.6, height: 7.56, type: "ground" }
        { id: "b4", x: -3.2, y: -2, width: 1.6, height: 8.36, type: "ground" }
        { id: "b5", x: -1.6, y: -2, width: 1.6, height: 8.84, type: "ground" }
        { id: "b6", x: 0, y: -2, width: 1.6, height: 9, type: "ground" }
        { id: "b7", x: 1.6, y: -2, width: 1.6, height: 8.68, type: "ground" }
        { id: "b8", x: 3.2, y: -2, width: 1.6, height: 7.72, type: "ground" }
        { id: "b9", x: 4.8, y: -2, width: 1.6, height: 6.12, type: "ground" }
        { id: "b10", x: 6.4, y: -2, width: 1.6, height: 3.88, type: "ground" }
