  trait RiyaContourPlay -> @rebindable RiyaContourState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit CONTOUR_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            guides: @entity.guides
            hops: @entity.hops
            keyMap: { ArrowLeft: "CONTOUR_LEFT", KeyA: "CONTOUR_LEFT", ArrowRight: "CONTOUR_RIGHT", KeyD: "CONTOUR_RIGHT", ArrowUp: "CONTOUR_JUMP", KeyW: "CONTOUR_JUMP", Space: "CONTOUR_JUMP" }
            keyUpMap: { ArrowLeft: "CONTOUR_STOP", KeyA: "CONTOUR_STOP", ArrowRight: "CONTOUR_STOP", KeyD: "CONTOUR_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (array/concat
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])
                    []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.9), vx: (* @entity.body.vx 0.5), vy: (* @entity.body.vy 0.5), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "CONTOUR_LEFT", right: "CONTOUR_RIGHT", up: "CONTOUR_JUMP" }, directionReleaseEvents: { left: "CONTOUR_STOP", right: "CONTOUR_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "contour")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.hops @payload.hops)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit CONTOUR_SET_PLATFORMS { platforms: @payload.platforms })
        (emit CONTOUR_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit CONTOUR_SET_FEATURES { features: @payload.stars })

      CONTOUR_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit CONTOUR_STEER { dir: -1 })

      CONTOUR_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit CONTOUR_STEER { dir: 1 })

      CONTOUR_STOP -> idle when (== @entity.active true)
        (emit CONTOUR_STEER { dir: 0 })

      CONTOUR_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit CONTOUR_LEAP {})

      CONTOUR_FELL -> idle when (== @entity.active true)
