  trait ContourChallenge -> @rebindable RiyaContourState [game-core, instance] {
    initial: idle

    state idle {
      CONTOUR_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "scale")
          (emit CONTOUR_BURST { particles: (array/concat
            { id: "narrative-boost-fact", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "∇f doubles", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            { id: "narrative-boost-hint", type: "narrative", x: @payload.x, z: (+ @payload.y 2.6), y: 0, message: "contours tighten", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          ) })
          null)
    }

    emits {
      CONTOUR_BURST -> external {
        particles : [RiyaContourFx]
      }
        @description "Particle batch spawned by the scale-pad narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      CONTOUR_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "contour"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaContourClear -> @rebindable RiyaContourState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "CONTOUR_NEXT", variant: "primary" } ]
        })

      CONTOUR_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
